ALTER TABLE public.stores ADD COLUMN IF NOT EXISTS translations jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS wilaya text;
ALTER TABLE public.menu_items ADD COLUMN IF NOT EXISTS translations jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS wilaya text, ADD COLUMN IF NOT EXISTS customer_user_id uuid;
CREATE TABLE public.order_security (order_id uuid PRIMARY KEY REFERENCES public.orders(id), customer_user_id uuid, device_id uuid NOT NULL, client_ip text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.order_security TO authenticated;
GRANT ALL ON public.order_security TO service_role;
ALTER TABLE public.order_security ENABLE ROW LEVEL SECURITY;
CREATE POLICY "owner reads order evidence" ON public.order_security FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'owner'));
CREATE TABLE public.customer_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id), courier_id uuid NOT NULL, reason text NOT NULL, details text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,courier_id));
GRANT SELECT, INSERT ON public.customer_reports TO authenticated;
GRANT ALL ON public.customer_reports TO service_role;
ALTER TABLE public.customer_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "courier reports assigned order" ON public.customer_reports FOR INSERT TO authenticated WITH CHECK (courier_id=auth.uid() AND public.has_role(auth.uid(),'courier') AND EXISTS(SELECT 1 FROM public.orders o WHERE o.id=order_id AND o.courier_id=auth.uid()));
CREATE POLICY "report read" ON public.customer_reports FOR SELECT TO authenticated USING (courier_id=auth.uid() OR public.has_role(auth.uid(),'owner'));
CREATE TABLE public.customer_bans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL UNIQUE REFERENCES public.customer_reports(id), customer_user_id uuid, device_id uuid, active boolean NOT NULL DEFAULT true, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.customer_bans TO authenticated;
GRANT ALL ON public.customer_bans TO service_role;
ALTER TABLE public.customer_bans ENABLE ROW LEVEL SECURITY;
CREATE POLICY "owner manages bans" ON public.customer_bans FOR ALL TO authenticated USING (public.has_role(auth.uid(),'owner')) WITH CHECK (public.has_role(auth.uid(),'owner'));
CREATE INDEX customer_bans_device_idx ON public.customer_bans(device_id) WHERE active;
CREATE INDEX customer_bans_user_idx ON public.customer_bans(customer_user_id) WHERE active;
CREATE INDEX orders_wilaya_sales_idx ON public.orders(wilaya,status);
REVOKE INSERT ON public.orders FROM anon, authenticated;
GRANT INSERT ON public.orders TO service_role;